  }
  const insertionIndex=document.blocks.slice(0,rawInsertionIndex).filter(block=>!isEmptyLayoutRow(block)).length;
  blocks=[...existingBlocks];
  blocks.splice(clampIndex(insertionIndex,blocks.length),0,...importedBlocks);
}

